export function facadeFrame(state,level=1,face=0){
 const levels=stack(state),total=levels.at(-1).z+levels.at(-1).h,l=levels[Math.max(0,Math.min(levels.length-1,Math.round(level)-1))],a=profile(state,l.z/total),b=profile(state,(l.z+l.h)/total),i=((Math.round(face)%a.length)+a.length)%a.length,j=(i+1)%a.length;
 const dx=a[j][0]-a[i][0],dy=a[j][1]-a[i][1],len=Math.hypot(dx,dy),u=[dx/len,dy/len],delta=[(b[i][0]+b[j][0]-a[i][0]-a[j][0])/2,(b[i][1]+b[j][1]-a[i][1]-a[j][1])/2];
 const radial=delta[0]*u[1]-delta[1]*u[0],tangent=delta[0]*u[0]+delta[1]*u[1];
 return {level:levels.indexOf(l)+1,count:levels.length,face:i,faces:a.length,height:l.h,radial,tangent,lean:Math.atan2(radial,l.h)*180/Math.PI};
}
